const startUrl = $('Page to scan').first().json.startUrl;
const html = String($input.first().json.data || '');
const m0 = startUrl.match(/^(https?:)\/\/([^\/?#]+)/i);
const proto = m0[1], host = m0[2].toLowerCase(), origin = proto + '//' + m0[2];
const baseDir = startUrl.split(/[?#]/)[0].replace(/[^\/]*$/, '');
function resolve(href) {
  let abs;
  if (/^https?:\/\//i.test(href)) abs = href;
  else if (href.startsWith('//')) abs = proto + href;
  else if (href.startsWith('/')) abs = origin + href;
  else abs = baseDir + href;
  const mm = abs.match(/^(https?:\/\/[^\/?#]+)([^?]*)(\?.*)?$/i);
  if (!mm) return null;
  const parts = [];
  for (const seg of mm[2].split('/')) {
    if (seg === '..') parts.pop(); else if (seg !== '.') parts.push(seg);
  }
  let path = parts.join('/');
  if (!path.startsWith('/')) path = '/' + path;
  return mm[1] + path + (mm[3] || '');
}
const seen = new Set();
const re = /href\s*=\s*["']([^"'#]+)[^"']*["']/gi;
let m;
while ((m = re.exec(html)) !== null) {
  const href = m[1].trim();
  if (!href || /^(mailto:|tel:|javascript:|data:)/i.test(href)) continue;
  const url = resolve(href);
  if (!url) continue;
  const h = url.replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].toLowerCase();
  if (h !== host) continue;
  seen.add(url);
  if (seen.size >= 200) break;
}
return [...seen].map(url => ({ json: { url } }));

const links = $('Extract links').all();
const broken = [];
$input.all().forEach((it, i) => {
  const status = Number(it.json.statusCode) || 0;
  if (status === 0 || status >= 400) {
    broken.push((links[i] ? links[i].json.url : 'unknown URL') + '  ->  ' + (status || 'no response'));
  }
});
if (broken.length === 0) return [];
return [{ json: { count: broken.length, checked: links.length, list: broken.join('\n') } }];
